function validate([details]) {
  if (!Array.isArray(details) || details.length < 1 || details.length > 100) return 'details needs 1 to 100 records.';
  const phones = new Set();
  const seats = new Set();
  for (const d of details) {
    if (typeof d !== 'string' || d.length !== 15) return 'Each record is exactly 15 characters long.';
    if (!/^[0-9]{10}[MFO][0-9]{4}$/.test(d)) return 'Each record is 10 digits, then M, F or O, then 4 digits.';
    if (phones.has(d.slice(0, 10))) return 'Phone numbers must all be different.';
    if (seats.has(d.slice(13))) return 'Seat numbers must all be different.';
    phones.add(d.slice(0, 10));
    seats.add(d.slice(13));
  }
  return null;
}

