function countSeniors(details) {
  let count = 0;
  for (const record of details) {
    const tens = record.charCodeAt(11) - 48;
    const ones = record.charCodeAt(12) - 48;
    const age = tens * 10 + ones;
    if (age > 60) {
      count++;
    }
  }
  return count;
}

