function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const digits = (len) => { let s = ''; for (let i = 0; i < len; i++) s += String(Math.floor(rand() * 10)); return s; };
  const genders = ['M', 'F', 'O'];
  const ages = [59, 60, 61, 0, 99, 1, 10];
  const phones = new Set();
  const seats = [];
  for (let s = 0; s < 100; s++) seats.push(String(s).padStart(2, '0'));
  for (let i = seats.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [seats[i], seats[j]] = [seats[j], seats[i]]; }
  const details = [];
  for (let i = 0; i < n; i++) {
    let phone = digits(10);
    while (phones.has(phone)) phone = digits(10);
    phones.add(phone);
    const age = rand() < 0.35 ? ages[Math.floor(rand() * ages.length)] : Math.floor(rand() * 100);
    details.push(phone + genders[Math.floor(rand() * 3)] + String(age).padStart(2, '0') + seats[i]);
  }
  return [details];
}
